mapper.select:
SELECT 
FROM crm_reminder_link
WHERE tenant_id = #{tenantId}
  AND token = #{token}

mapper.update:
UPDATE crm_reminder_link
SET status = 'revoked',
    update_time = NOW()
WHERE tenant_id = #{tenantId}
  AND ref_type = #{refType}
  AND ref_id = #{refId}
  AND status = 'active'

UPDATE crm_reminder_link
SET open_count = open_count + 1,
    opened_at = COALESCE(opened_at, NOW()),
    update_time = NOW()
WHERE id = #{id}
  AND tenant_id = #{tenantId}

UPDATE crm_reminder_link
SET status = 'expired',
    update_time = NOW()
WHERE id = #{id}
  AND tenant_id = #{tenantId}
  AND status = 'active'
